package io.clipbridge.android;
import org.json.*;
import java.security.*;
import java.util.*;
final class GroupSession {
    interface Save{void run()throws Exception;}interface Joined{void run(JSONObject group)throws Exception;}
    private final JSONObject identity,meta,connection;private JSONObject group,peer;private final GroupPake pake;private final GroupNetwork.Rendezvous signal;private final boolean host;private final Save save;private final Joined joined;
    final String code,link;String sas="",status="等待对方连接";boolean done,approved;private int stage;private boolean approvalSent,peerApproved,groupAdded,grantSent,finished,joinedApplied;private JSONObject second,third;private String ownHello="",peerHello="";private final Map<String,JSONObject> boxes=new HashMap<>();
    private GroupSession(JSONObject identity,GroupPake pake,GroupNetwork.Rendezvous signal,JSONObject meta,boolean host,String code,JSONObject connection,JSONObject group,Save save,Joined joined)throws Exception{this.identity=identity;this.pake=pake;this.signal=signal;this.meta=meta;this.host=host;this.code=code;this.connection=connection;this.group=group;this.save=save;this.joined=joined;link=GroupNetwork.link(connection,code);}
    static GroupSession invite(JSONObject group,JSONObject identity,Save save)throws Exception{GroupCrypto.validate(group);if(!group.optBoolean("enabled",true)||GroupCrypto.contains(group.getJSONArray("removed"),identity.getJSONObject("member").getString("id")))throw new IllegalStateException("此设备已退出或同步组已停用");String code=GroupPake.newCode();GroupPake pake=new GroupPake(code,true,commitment(identity.getJSONObject("member"),group.getString("id"),GroupCrypto.certHash(group.getJSONObject("root"))));JSONObject meta=new JSONObject().put("group",group.getString("id")).put("root",GroupCrypto.certHash(group.getJSONObject("root"))).put("expires",System.currentTimeMillis()/1000+300).put("first",pake.round1());GroupNetwork.Rendezvous signal=new GroupNetwork.Rendezvous(group.getJSONObject("connection"),code.substring(0,6),GroupCrypto.secret());signal.create(group,code.substring(0,6),meta);return new GroupSession(identity,pake,signal,meta,true,code,group.getJSONObject("connection"),group,save,null);}
    static GroupSession join(JSONObject connection,String code,JSONObject identity,Joined joined)throws Exception{code=GroupPake.normalize(code);GroupNetwork.Rendezvous signal=new GroupNetwork.Rendezvous(connection,code.substring(0,6),GroupCrypto.secret());JSONObject meta=signal.get("meta");if(meta==null)throw new IllegalArgumentException("邀请不存在或已过期");Protocol.id(meta.getString("group"));long expires=meta.getLong("expires");if(meta.getString("root").length()!=64||expires<=System.currentTimeMillis()/1000||expires>System.currentTimeMillis()/1000+360)throw new SecurityException("邀请已过期或数据无效");GroupPake pake=new GroupPake(code,false,commitment(identity.getJSONObject("member"),meta.getString("group"),meta.getString("root")));signal.put("b1",pake.round1());return new GroupSession(identity,pake,signal,meta,false,code,connection,null,()->{},joined);}
    private String own(){return host?"a":"b";}private String other(){return host?"b":"a";}
    private static String commitment(JSONObject member,String group,String root)throws Exception{return group+"\n"+root+"\n"+member.getString("id")+"\n"+GroupCrypto.b64(GroupCrypto.bytes(member.getString("name")))+"\n"+member.getString("signingKey")+"\n"+member.getString("agreementKey");}
    static byte[] helloData(JSONObject h,String code,String binding)throws Exception{JSONObject m=h.getJSONObject("member");return GroupCrypto.bytes("clipbridge:group-hello:1\n"+binding+"\n"+code.substring(0,6)+"\n"+h.getString("group")+"\n"+h.getString("root")+"\n"+h.getString("commitNonce")+"\n"+GroupCrypto.b64(GroupCrypto.bytes(h.getString("name")))+"\n"+m.getString("id")+"\n"+GroupCrypto.b64(GroupCrypto.bytes(m.getString("name")))+"\n"+m.getString("signingKey")+"\n"+m.getString("agreementKey"));}
    private void send(String slot,JSONObject data)throws Exception{JSONObject box=boxes.get(slot);if(box==null){box=pake.seal(slot,data.toString());boxes.put(slot,box);}signal.put(slot,box);}
    private JSONObject open(String slot,JSONObject box)throws Exception{return new JSONObject(pake.open(slot,box));}
    boolean ready(){return stage>=4&&!done;}JSONObject peer(){return peer;}long expires(){return meta.optLong("expires");}
    void approve(){if(!ready())throw new IllegalStateException();approved=true;status="已确认，等待对方确认";}
    void step()throws Exception{
        if(done)return;if(System.currentTimeMillis()/1000>=meta.getLong("expires"))throw new IllegalStateException("邀请已过期，请重新生成");String own=own(),other=other();
        if(stage==0){JSONObject first=host?signal.get("b1"):meta.getJSONObject("first");if(first==null)return;if(second==null)second=pake.round2(first);signal.put(own+"2",second);stage=1;status="正在验证配对口令";}
        if(stage==1){JSONObject peerRound=signal.get(other+"2");if(peerRound==null)return;if(third==null)third=pake.round3(peerRound);signal.put(own+"3",third);stage=2;}
        if(stage==2){JSONObject peerRound=signal.get(other+"3");if(peerRound==null)return;if(!finished){pake.finish(peerRound);finished=true;}if(ownHello.isEmpty()){JSONObject hello=new JSONObject().put("member",identity.getJSONObject("member")).put("group",meta.getString("group")).put("name",host?group.getString("name"):"").put("root",meta.getString("root")).put("commitNonce",pake.commitNonce);hello.put("signature",GroupCrypto.sign(identity,helloData(hello,code,pake.binding())));ownHello=hello.toString();}send(own+"hello",new JSONObject(ownHello));stage=3;}
        if(stage==3){JSONObject box=signal.get(other+"hello");if(box==null)return;peerHello=pake.open(other+"hello",box);JSONObject hello=new JSONObject(peerHello);GroupCrypto.member(hello.getJSONObject("member"));peer=hello.getJSONObject("member");if(!hello.getString("group").equals(meta.getString("group"))||!hello.getString("root").equals(meta.getString("root"))||peer.getString("id").equals(identity.getJSONObject("member").getString("id"))||!pake.verifyCommitment(commitment(peer,hello.getString("group"),hello.getString("root")),hello.getString("commitNonce"))||!GroupCrypto.verify(peer,helloData(hello,code,pake.binding()),hello.getString("signature")))throw new SecurityException("设备身份验证失败");if(host&&(group.getJSONObject("members").has(peer.getString("id"))&&!GroupCrypto.contains(group.getJSONArray("removed"),peer.getString("id"))))throw new IllegalStateException("此设备已在组内或曾被移出，请勿重复加入");sas=pake.sas(host?ownHello:peerHello,host?peerHello:ownHello);stage=4;status="请核对两端的安全码并分别确认";}
        if(stage==4){String a=host?ownHello:peerHello,b=host?peerHello:ownHello;if(approved&&!approvalSent){send(own+"approval",new JSONObject().put("accepted",true).put("proof",pake.proof(identity,peer,a,b,own)));approvalSent=true;}
            if(!peerApproved){JSONObject box=signal.get(other+"approval");if(box!=null){JSONObject approval=open(other+"approval",box);if(!approval.getBoolean("accepted")||!MessageDigest.isEqual(GroupCrypto.un64(approval.getString("proof")),GroupCrypto.un64(pake.proof(identity,peer,a,b,other))))throw new SecurityException("设备密钥确认失败");peerApproved=true;}}
            if(!approved||!peerApproved)return;
            if(host){if(!groupAdded){GroupCrypto.addMember(group,identity,peer);groupAdded=true;}save.run();if(!grantSent){GroupNetwork.publish(group,identity);send("grant",GroupCrypto.exported(group));grantSent=true;}stage=5;status="已授权，等待新设备完成入组";}
            else{JSONObject box=signal.get("grant");if(box==null)return;JSONObject received=open("grant",box);GroupCrypto.validate(received);JSONObject members=received.getJSONObject("members");String selfId=identity.getJSONObject("member").getString("id"),peerId=peer.getString("id");if(!received.getString("id").equals(meta.getString("group"))||!GroupCrypto.certHash(received.getJSONObject("root")).equals(meta.getString("root"))||!members.has(selfId)||!GroupCrypto.same(members.getJSONObject(selfId).getJSONObject("member"),identity.getJSONObject("member"))||!members.has(peerId)||!GroupCrypto.same(members.getJSONObject(peerId).getJSONObject("member"),peer)||GroupCrypto.contains(received.getJSONArray("removed"),selfId)||GroupCrypto.contains(received.getJSONArray("removed"),peerId))throw new SecurityException("入组授权与当前设备不一致");JSONObject history=GroupNetwork.read(received,selfId);if(history!=null){if(!history.getString("group").equals(received.getString("id"))||!history.getString("author").equals(selfId)||!GroupCrypto.verify(identity.getJSONObject("member"),GroupCrypto.feedData(history),history.getString("signature")))throw new SecurityException("本机历史成员清单无效");JSONObject cached=received.getJSONObject("feeds").optJSONObject(selfId);if(cached==null||history.getLong("sequence")>cached.getLong("sequence"))received.getJSONObject("feeds").put(selfId,history);}received.put("ownCertificates",new JSONArray()).put("ownRemoved",new JSONArray()).put("sequence",1);if(!joinedApplied){joined.run(received);joinedApplied=true;}group=received;send("done",new JSONObject().put("accepted",true).put("proof",""));done=true;status="已加入同步组，正在连接其他成员";}
        }
        if(stage==5){JSONObject box=signal.get("done");if(box!=null&&open("done",box).getBoolean("accepted")){done=true;status="新设备已加入同步组";}}
    }
    void close(){pake.close();}
}
